-- =====================================================================
-- 0008_semana1_e_bloqueio.sql
-- BodyMy — Conteúdo real da Semana 1 (v1) + bloqueio das semanas 2-4.
--
-- GERADO por scripts/gen-circuito-semana1.ts a partir de
-- supabase/content/circuito-semana1.ts. NÃO edite à mão — regenere.
-- Idempotente: pode rodar mais de uma vez.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1) BLOQUEIO DE SEMANAS
-- ---------------------------------------------------------------------
create table if not exists public.program_weeks_config (
  semana int primary key check (semana between 1 and 4),
  liberada boolean not null default false,
  atualizado_em timestamptz not null default now()
);
alter table public.program_weeks_config enable row level security;
drop policy if exists "pwc_read_auth" on public.program_weeks_config;
create policy "pwc_read_auth" on public.program_weeks_config
  for select to authenticated using (true);

-- Semana 1 sempre liberada; 2-4 bloqueadas por padrão.
insert into public.program_weeks_config (semana, liberada)
values (1, true), (2, false), (3, false), (4, false)
on conflict (semana) do nothing;
update public.program_weeks_config set liberada = true where semana = 1;

-- Registro de que a aluna concluiu o ciclo e aguarda a liberação da próxima
-- semana (0 = não aguarda). Usado para métrica e para o "avança no próximo
-- acesso" quando o Willian libera.
alter table public.user_training_config
  add column if not exists aguardando_liberacao int not null default 0;

-- ---------------------------------------------------------------------
-- 2) CONTEÚDO DA SEMANA 1 (v1) + ALONGAMENTOS
-- ---------------------------------------------------------------------
do $conteudo$
declare
  v_ex   jsonb := $ex$[{"dia":1,"ordem":1,"nome":"Respiração de três tempos","descricao":"Dia 1 — Respirar e assentar","instrucoes":"Preparação: Deitada de costas, joelhos dobrados, pés apoiados no chão. Uma mão sobre o ventre, outra sobre o peito.\nMovimento: Deixe o ar entrar primeiro enchendo o ventre, depois as costelas, por último o peito. Solte na ordem inversa, sem pressa.\nRespiração: Inspire em 4 tempos, solte em 6. Sem prender o ar em nenhum momento.\nO que sentir: A mão do ventre subindo antes da mão do peito. É comum que, no começo, aconteça o contrário — tudo bem.\nAtenção: Se sentir tontura, volte a respirar normalmente por alguns instantes."},{"dia":1,"ordem":2,"nome":"Balanço da pelve","descricao":"Dia 1 — Respirar e assentar","instrucoes":"Preparação: Deitada de costas, joelhos dobrados, pés apoiados na largura do quadril.\nMovimento: Incline a pelve levemente para trás, colando a lombar no chão. Depois volte devagar, deixando um pequeno espaço embaixo da lombar. Movimento pequeno, quase invisível de fora.\nRespiração: Solte o ar ao colar a lombar, inspire ao voltar.\nO que sentir: A lombar tocando e descolando do chão. O movimento nasce da pelve, não das pernas.\nAtenção: Não force a lombar contra o chão. É um balanço suave, não uma pressão."},{"dia":1,"ordem":3,"nome":"Joelhos que se abraçam","descricao":"Dia 1 — Respirar e assentar","instrucoes":"Preparação: Deitada de costas. Traga um joelho de cada vez em direção ao peito e envolva-os com as mãos ou os braços.\nMovimento: Puxe os joelhos suavemente em direção ao peito, sustente por três respirações e solte um pouco. Repita.\nRespiração: Solte o ar ao aproximar os joelhos, inspire ao afrouxar.\nO que sentir: Um alongamento agradável na lombar e nos glúteos.\nAtenção: Se o pescoço tensionar, apoie a cabeça em uma almofada baixa."},{"dia":1,"ordem":4,"nome":"Pés que empurram","descricao":"Dia 1 — Respirar e assentar","instrucoes":"Preparação: Deitada de costas, joelhos dobrados, pés bem apoiados no chão.\nMovimento: Pressione os pés contra o chão como se fosse empurrar o chão para longe, sem levantar o quadril. Sustente dois segundos e solte completamente.\nRespiração: Solte o ar ao pressionar, inspire ao relaxar.\nO que sentir: Ativação atrás das coxas e nos glúteos, sem esforço na lombar.\nAtenção: O quadril permanece no chão. Se ele subir, reduza a força."},{"dia":1,"ordem":5,"nome":"Descanso da lombar","descricao":"Dia 1 — Respirar e assentar","instrucoes":"Preparação: Deitada de costas, panturrilhas apoiadas sobre o assento de uma cadeira ou sofá, joelhos em ângulo reto.\nMovimento: Nenhum. Apenas permaneça na posição, deixando o peso do corpo afundar.\nRespiração: Livre e natural. Observe o ar entrando e saindo.\nO que sentir: A lombar se soltando aos poucos. É comum sentir o corpo “afundar” após o primeiro minuto.\nAtenção: Permaneça de 2 a 3 minutos. Se sentir formigamento nas pernas, baixe-as e recomece."},{"dia":2,"ordem":1,"nome":"Ombros que derretem","descricao":"Dia 2 — Soltar o alto do corpo","instrucoes":"Preparação: Sentada em uma cadeira, pés apoiados no chão, coluna apoiada no encosto.\nMovimento: Suba os ombros em direção às orelhas lentamente, sustente por três segundos, e deixe cair de uma vez, como se soltasse um peso.\nRespiração: Inspire ao subir, solte o ar ao deixar cair.\nO que sentir: O contraste entre a tensão e o relaxamento. É essa diferença que ensina o corpo a soltar.\nAtenção: A queda é passiva, não empurre os ombros para baixo."},{"dia":2,"ordem":2,"nome":"Cabeça que rola","descricao":"Dia 2 — Soltar o alto do corpo","instrucoes":"Preparação: Sentada, coluna apoiada, ombros relaxados.\nMovimento: Leve o queixo em direção ao peito e role a cabeça devagar para um lado, depois volte ao centro e vá para o outro. Meio círculo apenas, nunca para trás.\nRespiração: Livre, sem prender.\nO que sentir: Alongamento nas laterais do pescoço. Pode haver leves estalos — é normal.\nAtenção: Nunca leve a cabeça para trás. Se sentir tontura, pare e volte ao centro."},{"dia":2,"ordem":3,"nome":"Braços de asa","descricao":"Dia 2 — Soltar o alto do corpo","instrucoes":"Preparação: Sentada, braços dobrados na altura do peito, cotovelos na altura dos ombros.\nMovimento: Abra os cotovelos para os lados, aproximando as escápulas, e volte à frente. Movimento horizontal e lento.\nRespiração: Inspire ao abrir, solte o ar ao fechar.\nO que sentir: As escápulas se aproximando nas costas ao abrir.\nAtenção: Os ombros permanecem baixos. Se subirem em direção às orelhas, reduza a amplitude."},{"dia":2,"ordem":4,"nome":"Peito que abre","descricao":"Dia 2 — Soltar o alto do corpo","instrucoes":"Preparação: Sentada na beira da cadeira, mãos apoiadas atrás do quadril, dedos apontando para trás.\nMovimento: Deslize as mãos um pouco mais para trás, abrindo o peito, e sustente por três respirações. Volte e repita.\nRespiração: Inspire profundamente na abertura, sentindo o peito expandir.\nO que sentir: Abertura na frente do peito e dos ombros.\nAtenção: Mantenha o pescoço longo. Não jogue a cabeça para trás."},{"dia":2,"ordem":5,"nome":"Nuca longa","descricao":"Dia 2 — Soltar o alto do corpo","instrucoes":"Preparação: Sentada, coluna apoiada, mãos sobre as coxas.\nMovimento: Leve o queixo em direção ao peito devagar, alongando a nuca. Sustente e volte lentamente. Depois incline a cabeça para cada lado, orelha em direção ao ombro.\nRespiração: Solte o ar ao inclinar, inspire ao voltar ao centro.\nO que sentir: Alongamento na nuca e nas laterais do pescoço.\nAtenção: Não use as mãos para puxar a cabeça. Deixe o peso dela fazer o trabalho."},{"dia":3,"ordem":1,"nome":"Quadril que balança","descricao":"Dia 3 — Abrir os quadris","instrucoes":"Preparação: Deitada de costas, joelhos dobrados, pés apoiados.\nMovimento: Deslize o quadril suavemente para um lado e para o outro, como um balanço lento. Movimento pequeno.\nRespiração: Livre, acompanhando o ritmo do balanço.\nO que sentir: Soltura na região do quadril e da lombar.\nAtenção: Os ombros permanecem apoiados. O movimento é só do quadril para baixo."},{"dia":3,"ordem":2,"nome":"Joelho que abre","descricao":"Dia 3 — Abrir os quadris","instrucoes":"Preparação: Deitada de costas, joelhos dobrados, pés apoiados.\nMovimento: Deixe um joelho abrir para o lado, em direção ao chão, mantendo o pé apoiado. Vá até onde for confortável e volte. Alterne os lados.\nRespiração: Solte o ar ao abrir, inspire ao voltar.\nO que sentir: Abertura na virilha e na parte interna da coxa.\nAtenção: O quadril do lado oposto permanece apoiado. Não force o joelho até o chão."},{"dia":3,"ordem":3,"nome":"Borboleta deitada","descricao":"Dia 3 — Abrir os quadris","instrucoes":"Preparação: Deitada de costas, plantas dos pés unidas, joelhos abertos para os lados.\nMovimento: Permaneça na posição deixando o peso das pernas abrir os joelhos naturalmente. Se preferir, apoie almofadas embaixo dos joelhos.\nRespiração: Livre e profunda. A cada expiração, imagine os quadris soltando um pouco mais.\nO que sentir: Alongamento na parte interna das coxas.\nAtenção: Nunca empurre os joelhos para baixo com as mãos. Permaneça de 1 a 2 minutos."},{"dia":3,"ordem":4,"nome":"Perna que desliza","descricao":"Dia 3 — Abrir os quadris","instrucoes":"Preparação: Deitada de costas, joelhos dobrados, pés apoiados.\nMovimento: Deslize um calcanhar pelo chão, estendendo a perna até onde conseguir manter a lombar tranquila. Volte deslizando. Alterne.\nRespiração: Solte o ar ao estender, inspire ao recolher.\nO que sentir: O trabalho suave na frente da coxa e no centro do corpo ao controlar o movimento.\nAtenção: Se a lombar arquear muito, estenda menos a perna."},{"dia":3,"ordem":5,"nome":"Figura quatro","descricao":"Dia 3 — Abrir os quadris","instrucoes":"Preparação: Deitada de costas, joelhos dobrados. Cruze o tornozelo direito sobre a coxa esquerda, formando um “quatro”.\nMovimento: Permaneça na posição. Se quiser mais intensidade, aproxime a coxa de apoio do peito com as mãos.\nRespiração: Livre. Três a cinco respirações de cada lado.\nO que sentir: Alongamento no glúteo da perna cruzada.\nAtenção: Se sentir desconforto no joelho, reduza ou saia da posição."},{"dia":4,"ordem":1,"nome":"Gato e vaca no chão","descricao":"Dia 4 — Coluna viva","instrucoes":"Preparação: Em quatro apoios, mãos sob os ombros, joelhos sob o quadril. Se os joelhos incomodarem, use uma toalha dobrada.\nMovimento: Arredonde as costas levando o olhar ao umbigo, depois inverta, deixando a barriga descer e o olhar subir levemente. Alterne lentamente.\nRespiração: Solte o ar ao arredondar, inspire ao abrir.\nO que sentir: A coluna se movendo por inteiro, vértebra por vértebra.\nAtenção: Amplitude confortável. Se o punho incomodar, apoie os antebraços."},{"dia":4,"ordem":2,"nome":"Coluna que desenrola","descricao":"Dia 4 — Coluna viva","instrucoes":"Preparação: Sentada na beira da cadeira, pés apoiados, mãos sobre as coxas.\nMovimento: Enrole a coluna para frente devagar, começando pela cabeça, deixando as mãos deslizarem pelas coxas. Volte desenrolando de baixo para cima.\nRespiração: Solte o ar ao descer, inspire ao subir.\nO que sentir: Cada parte da coluna se dobrando e voltando em sequência.\nAtenção: Desça só até onde for confortável. Não precisa alcançar os pés."},{"dia":4,"ordem":3,"nome":"Torção do relógio","descricao":"Dia 4 — Coluna viva","instrucoes":"Preparação: Deitada de costas, joelhos dobrados e unidos, braços abertos em cruz.\nMovimento: Deixe os joelhos caírem devagar para um lado, mantendo os ombros apoiados. Volte ao centro e vá para o outro lado.\nRespiração: Solte o ar ao girar, inspire ao voltar.\nO que sentir: Rotação suave na coluna e alongamento na lateral do tronco.\nAtenção: Se um ombro levantar do chão, reduza a amplitude da torção."},{"dia":4,"ordem":4,"nome":"Ondulação da coluna","descricao":"Dia 4 — Coluna viva","instrucoes":"Preparação: Em quatro apoios, mãos sob os ombros.\nMovimento: Faça um movimento contínuo e ondulatório, como uma onda que percorre a coluna do cóccix até a cabeça, e volta.\nRespiração: Livre, acompanhando o ritmo da onda.\nO que sentir: O movimento passando por regiões da coluna que costumam ficar paradas.\nAtenção: É um movimento fluido, sem paradas. Se ficar confuso, volte ao gato e vaca."},{"dia":4,"ordem":5,"nome":"Alongamento em C","descricao":"Dia 4 — Coluna viva","instrucoes":"Preparação: Sentada, uma mão apoiada no assento ao lado do quadril.\nMovimento: Leve o outro braço por cima da cabeça, inclinando o tronco para o lado e formando um arco. Sustente e volte. Alterne.\nRespiração: Inspire ao subir o braço, solte o ar na inclinação.\nO que sentir: Alongamento em toda a lateral do tronco, das costelas ao quadril.\nAtenção: Mantenha os dois glúteos apoiados no assento."},{"dia":5,"ordem":1,"nome":"Barriga que respira","descricao":"Dia 5 — Centro sem esforço","instrucoes":"Preparação: Deitada de costas, joelhos dobrados, mãos sobre a barriga.\nMovimento: Ao soltar o ar, leve o umbigo suavemente em direção à coluna, como se fechasse um cinto por dentro. Solte ao inspirar.\nRespiração: A ativação acontece na expiração. Nunca prenda o ar.\nO que sentir: Uma ativação profunda e sutil no fundo da barriga — não é contrair com força.\nAtenção: Se a barriga endurecer por fora ou o ar ficar preso, está forçando demais."},{"dia":5,"ordem":2,"nome":"Perna que cai e volta","descricao":"Dia 5 — Centro sem esforço","instrucoes":"Preparação: Deitada de costas, joelhos dobrados, pés apoiados, mãos ao lado do corpo.\nMovimento: Ative suavemente a barriga e deixe um joelho abrir para o lado, mantendo o quadril estável. Volte com controle. Alterne.\nRespiração: Solte o ar ao abrir, inspire ao voltar.\nO que sentir: O centro do corpo trabalhando para impedir que o quadril gire junto.\nAtenção: Se o quadril oposto levantar, reduza a amplitude."},{"dia":5,"ordem":3,"nome":"Cabeça que levanta devagar","descricao":"Dia 5 — Centro sem esforço","instrucoes":"Preparação: Deitada de costas, joelhos dobrados, mãos atrás da cabeça apenas como apoio.\nMovimento: Solte o ar, leve o queixo levemente em direção ao peito e eleve a cabeça poucos centímetros. Volte devagar.\nRespiração: Solte o ar ao subir, inspire ao descer.\nO que sentir: Ativação na barriga, não no pescoço.\nAtenção: As mãos apoiam, não puxam. Se o pescoço doer, pare."},{"dia":5,"ordem":4,"nome":"Ponte suave","descricao":"Dia 5 — Centro sem esforço","instrucoes":"Preparação: Deitada de costas, joelhos dobrados, pés apoiados na largura do quadril.\nMovimento: Eleve o quadril alguns centímetros do chão e desça devagar, apoiando vértebra por vértebra.\nRespiração: Solte o ar ao subir, inspire ao descer.\nO que sentir: Ativação nos glúteos e atrás das coxas.\nAtenção: Não suba além do confortável. Se a lombar reclamar, eleve menos."},{"dia":5,"ordem":5,"nome":"Prancha apoiada","descricao":"Dia 5 — Centro sem esforço","instrucoes":"Preparação: Em pé, de frente para uma parede, mãos apoiadas na altura dos ombros, pés a um passo de distância.\nMovimento: Mantenha o corpo em linha reta da cabeça aos pés, barriga levemente ativa. Sustente por 15 a 20 segundos.\nRespiração: Contínua e tranquila. Não prenda o ar.\nO que sentir: Ativação suave em todo o centro do corpo.\nAtenção: Se a lombar afundar, aproxime os pés da parede."},{"dia":6,"ordem":1,"nome":"Agachamento na cadeira","descricao":"Dia 6 — Pernas e apoio","instrucoes":"Preparação: Em pé, de costas para uma cadeira, pés na largura do quadril.\nMovimento: Desça sentando na cadeira com controle, apoiando as mãos nos joelhos se precisar. Levante usando a força das pernas.\nRespiração: Inspire ao descer, solte o ar ao subir.\nO que sentir: Trabalho na frente das coxas e nos glúteos.\nAtenção: Os joelhos apontam na mesma direção dos pés. Desça devagar, sem se jogar."},{"dia":6,"ordem":2,"nome":"Panturrilha que sobe","descricao":"Dia 6 — Pernas e apoio","instrucoes":"Preparação: Em pé, mãos apoiadas no encosto de uma cadeira ou na parede.\nMovimento: Suba os calcanhares, ficando na ponta dos pés, sustente um segundo e desça devagar.\nRespiração: Solte o ar ao subir, inspire ao descer.\nO que sentir: Trabalho nas panturrilhas e ativação nos pés.\nAtenção: A descida é lenta — é nela que está o trabalho."},{"dia":6,"ordem":3,"nome":"Perna que abre em pé","descricao":"Dia 6 — Pernas e apoio","instrucoes":"Preparação: Em pé, uma mão apoiada na parede ou cadeira.\nMovimento: Abra uma perna para o lado até onde conseguir manter o tronco reto, e volte com controle. Alterne.\nRespiração: Solte o ar ao abrir, inspire ao voltar.\nO que sentir: Trabalho na lateral do quadril.\nAtenção: O tronco permanece ereto. Não incline para o lado oposto."},{"dia":6,"ordem":4,"nome":"Passo que atrasa","descricao":"Dia 6 — Pernas e apoio","instrucoes":"Preparação: Em pé, mão apoiada em uma cadeira, pés na largura do quadril.\nMovimento: Dê um passo para trás com uma perna, transferindo pouco peso, e volte ao centro. Alterne.\nRespiração: Inspire ao dar o passo, solte o ar ao voltar.\nO que sentir: Equilíbrio e trabalho na perna de apoio.\nAtenção: Passo curto no começo. Aumente conforme a segurança."},{"dia":6,"ordem":5,"nome":"Equilíbrio de um pé","descricao":"Dia 6 — Pernas e apoio","instrucoes":"Preparação: Em pé, ao lado de uma parede ou cadeira, com a mão pousada de leve como segurança.\nMovimento: Eleve um pé poucos centímetros do chão e mantenha o equilíbrio por 10 a 20 segundos. Alterne.\nRespiração: Tranquila e contínua.\nO que sentir: Os pequenos ajustes constantes do pé e do tornozelo — é assim que o equilíbrio se treina.\nAtenção: Mantenha sempre o apoio ao alcance da mão."},{"dia":7,"ordem":1,"nome":"Espreguiçar completo","descricao":"Dia 7 — Corpo inteiro, devagar","instrucoes":"Preparação: Deitada de costas, pernas estendidas, braços acima da cabeça.\nMovimento: Estique o corpo inteiro como ao acordar: braços para cima, pés para baixo, alongando ao máximo. Sustente e solte de uma vez.\nRespiração: Inspire ao esticar, solte o ar ao relaxar.\nO que sentir: O corpo inteiro se alongando de ponta a ponta, e o relaxamento profundo depois.\nAtenção: Este é o movimento mais natural que existe. Deixe o corpo conduzir."},{"dia":7,"ordem":2,"nome":"Rolar para o lado","descricao":"Dia 7 — Corpo inteiro, devagar","instrucoes":"Preparação: Deitada de costas, braços ao lado do corpo.\nMovimento: Role o corpo inteiro para um lado com controle, como um bloco só, e volte. Alterne.\nRespiração: Livre, acompanhando o movimento.\nO que sentir: A coordenação entre tronco, quadril e pernas.\nAtenção: Movimento lento. A intenção é sentir a sequência, não a velocidade."},{"dia":7,"ordem":3,"nome":"Sequência do levantar","descricao":"Dia 7 — Corpo inteiro, devagar","instrucoes":"Preparação: Deitada de costas.\nMovimento: Role para o lado, apoie a mão no chão, sente-se, apoie-se para ficar de joelhos e levante-se. Depois faça o caminho inverso para voltar ao chão.\nRespiração: Livre, sem prender em nenhuma transição.\nO que sentir: Como o corpo se organiza para sair do chão — um gesto que usamos a vida toda sem perceber.\nAtenção: Use apoio sempre que precisar. Vá devagar."},{"dia":7,"ordem":4,"nome":"Balanço em pé","descricao":"Dia 7 — Corpo inteiro, devagar","instrucoes":"Preparação: Em pé, pés na largura do quadril, braços soltos.\nMovimento: Balance o corpo suavemente para frente e para trás, depois para os lados, encontrando o ponto de equilíbrio no centro.\nRespiração: Livre e tranquila.\nO que sentir: Os pés trabalhando o tempo todo para manter você em pé.\nAtenção: Movimento pequeno. Se sentir instabilidade, fique perto de uma parede."},{"dia":7,"ordem":5,"nome":"Silêncio do corpo","descricao":"Dia 7 — Corpo inteiro, devagar","instrucoes":"Preparação: Deitada de costas, pernas estendidas ou joelhos dobrados, o que for mais confortável.\nMovimento: Nenhum. Apenas permaneça, percorrendo o corpo com a atenção, dos pés à cabeça.\nRespiração: Natural. Sem controlar.\nO que sentir: Como o corpo está agora, depois da semana inteira de prática.\nAtenção: Permaneça de 2 a 3 minutos. Este é o fechamento — não pule."}]$ex$::jsonb;
  v_st   jsonb := $st$[{"ordem":1,"nome":"Respirar e chegar","descricao":"Deitada de costas, joelhos dobrados. Apenas respire por três minutos, observando o ar entrar e sair. Sem mover nada. É o primeiro contato com o corpo."},{"ordem":2,"nome":"Alongar de ponta a ponta","descricao":"Deitada, braços acima da cabeça. Estique o corpo inteiro por alguns segundos e solte. Repita três vezes."},{"ordem":3,"nome":"Joelhos ao peito","descricao":"Deitada, traga os joelhos ao peito e envolva com os braços. Sustente por cinco respirações, sentindo a lombar apoiada no chão."},{"ordem":4,"nome":"Torção deitada","descricao":"Deitada, joelhos dobrados e unidos, braços abertos. Deixe os joelhos caírem para um lado e o olhar para o outro. Cinco respirações de cada lado."},{"ordem":5,"nome":"Pescoço em três direções","descricao":"Sentada. Incline a cabeça para a direita, para a esquerda e para frente, sustentando três respirações em cada posição. Nunca para trás."},{"ordem":6,"nome":"Ombros em círculo","descricao":"Sentada. Faça círculos lentos com os ombros, cinco vezes para trás e cinco para frente."},{"ordem":7,"nome":"Abrir os braços","descricao":"Sentada na beira da cadeira, mãos apoiadas atrás. Abra o peito e sustente por cinco respirações."},{"ordem":8,"nome":"Alongar atrás da perna","descricao":"Sentada, uma perna estendida à frente com o calcanhar no chão. Incline o tronco levemente até sentir a parte de trás da perna. Cinco respirações de cada lado."},{"ordem":9,"nome":"Quadril em quatro","descricao":"Deitada, tornozelo cruzado sobre a coxa oposta. Sustente por cinco respirações de cada lado."},{"ordem":10,"nome":"Repouso final","descricao":"Deitada, pernas e braços soltos. Dois minutos de imobilidade, apenas percebendo o corpo."}]$st$::jsonb;
  r      jsonb;
  v_exercise_id uuid;
begin
  -- Exercícios: nome + descrição (por dia/ordem) e instruções da v1.
  for r in select * from jsonb_array_elements(v_ex)
  loop
    update public.exercises
       set nome = r->>'nome', descricao = r->>'descricao'
     where dia_do_ciclo = (r->>'dia')::int
       and ordem_no_dia = (r->>'ordem')::int
    returning id into v_exercise_id;

    if v_exercise_id is not null then
      update public.exercise_variations
         set instrucoes = r->>'instrucoes'
       where exercise_id = v_exercise_id and nivel = 1;
    end if;
  end loop;

  -- Alongamentos da Semana Zero.
  for r in select * from jsonb_array_elements(v_st)
  loop
    update public.stretches
       set nome = r->>'nome', descricao = r->>'descricao'
     where ordem = (r->>'ordem')::int;
  end loop;
end
$conteudo$;

notify pgrst, 'reload schema';

-- ---------------------------------------------------------------------
-- VERIFICAÇÃO
-- ---------------------------------------------------------------------
select * from (values
  ('semanas configuradas (esperado 4)', (select count(*)::text from public.program_weeks_config)),
  ('semana 1 liberada', (select case when (select liberada from public.program_weeks_config where semana=1) then 'sim' else 'NAO' end)),
  ('semanas 2-4 bloqueadas', (select count(*)::text from public.program_weeks_config where semana in (2,3,4) and liberada = false)),
  ('exercicios renomeados (sem "Exercício N")', (select count(*)::text from public.exercises where nome !~ '^Exercício [0-9]+$')),
  ('variacoes v1 com instrucoes (esperado 35)', (select count(*)::text from public.exercise_variations where nivel=1 and instrucoes is not null)),
  ('alongamentos renomeados (sem "Alongamento N")', (select count(*)::text from public.stretches where nome !~ '^Alongamento [0-9]+$'))
) as v(verificacao, valor) order by verificacao;
